CREATE VIEW std_user_game_assessment_candidates AS SELECT g.GameID, COALESCE(max(s.difficulty_rating) FILTER (WHERE (s.platform_name = 'PS5')), max(s.difficulty_rating) FILTER (WHERE (s.platform_name = 'PS4')), max(s.difficulty_rating) FILTER (WHERE (s.platform_name = 'Wii U'))) AS difficulty_rating, COALESCE(max(s.base_length_hours) FILTER (WHERE (s.platform_name = 'PS5')), max(s.base_length_hours) FILTER (WHERE (s.platform_name = 'PS4')), max(s.base_length_hours) FILTER (WHERE (s.platform_name = 'Wii U'))) AS base_length_hours, COALESCE(max(s.full_completion_hours) FILTER (WHERE (s.platform_name = 'PS5')), max(s.full_completion_hours) FILTER (WHERE (s.platform_name = 'PS4')), max(s.full_completion_hours) FILTER (WHERE (s.platform_name = 'Wii U'))) AS full_completion_hours FROM std_inventory_game_ready AS s INNER JOIN Game AS g ON ((g.GameTitle = s.game_title)) GROUP BY g.GameID HAVING ((COALESCE(max(s.difficulty_rating) FILTER (WHERE (s.platform_name = 'PS5')), max(s.difficulty_rating) FILTER (WHERE (s.platform_name = 'PS4')), max(s.difficulty_rating) FILTER (WHERE (s.platform_name = 'Wii U'))) IS NOT NULL) OR (COALESCE(max(s.base_length_hours) FILTER (WHERE (s.platform_name = 'PS5')), max(s.base_length_hours) FILTER (WHERE (s.platform_name = 'PS4')), max(s.base_length_hours) FILTER (WHERE (s.platform_name = 'Wii U'))) IS NOT NULL) OR (COALESCE(max(s.full_completion_hours) FILTER (WHERE (s.platform_name = 'PS5')), max(s.full_completion_hours) FILTER (WHERE (s.platform_name = 'PS4')), max(s.full_completion_hours) FILTER (WHERE (s.platform_name = 'Wii U'))) IS NOT NULL));
